import React, { useState, useEffect } from 'react';
import api from '../api';

function VolunteerDashboard({ volunteerId, onLogout }) {
  const [volunteer, setVolunteer] = useState(null);
  const [assignments, setAssignments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [message, setMessage] = useState('');

  useEffect(() => {
    fetchVolunteerData();
  }, [volunteerId]);

  const fetchVolunteerData = async () => {
    setLoading(true);
    try {
      const [volunteerRes, assignmentsRes] = await Promise.all([
        api.get(`/api/volunteers/${volunteerId}`),
        api.get(`/api/assignments/volunteer/${volunteerId}`)
      ]);

      if (volunteerRes.data.success) {
        setVolunteer(volunteerRes.data.data);
      }

      if (assignmentsRes.data.success) {
        setAssignments(assignmentsRes.data.data);
      }
    } catch (error) {
      console.error('Error fetching volunteer data:', error);
      showMessage('Error loading data', 'error');
    } finally {
      setLoading(false);
    }
  };

  const showMessage = (msg, type = 'success') => {
    setMessage({ text: msg, type });
    setTimeout(() => setMessage(''), 3000);
  };

  const handleUpdateStatus = async (assignmentId, newStatus) => {
    try {
      const response = await axios.patch(
        `/api/assignments/${assignmentId}/status`,
        { status: newStatus }
      );

      if (response.data.success) {
        showMessage('Status updated successfully!');
        fetchVolunteerData();
      }
    } catch (error) {
      showMessage(error.response?.data?.message || 'Error updating status', 'error');
    }
  };

  if (loading) {
    return (
      <div className="dashboard">
        <div className="main-content">
          <div className="loading">Loading...</div>
        </div>
      </div>
    );
  }

  if (!volunteer) {
    return (
      <div className="dashboard">
        <div className="main-content">
          <div className="error-message">Volunteer not found</div>
        </div>
      </div>
    );
  }

  const pendingAssignments = assignments.filter(a => a.status === 'pending');
  const inProgressAssignments = assignments.filter(a => a.status === 'in-progress');
  const completedAssignments = assignments.filter(a => a.status === 'completed');

  return (
    <div className="dashboard">
      {/* Sidebar */}
      <div className="sidebar">
        <h2>Volunteer Portal</h2>
        <div style={{ padding: '15px', background: '#34495e', borderRadius: '5px', marginBottom: '20px' }}>
          <p style={{ fontSize: '14px', marginBottom: '5px' }}>Welcome,</p>
          <p style={{ fontSize: '18px', fontWeight: 'bold' }}>{volunteer.name}</p>
          <p style={{ fontSize: '12px', color: '#bdc3c7' }}>{volunteer.email}</p>
        </div>
        <ul className="nav-menu">
          <li className="nav-item active">
            📋 My Assignments
          </li>
          <li className="nav-item">
            👤 Profile
          </li>
        </ul>
        <button className="logout-button" onClick={onLogout}>
          Logout
        </button>
      </div>

      {/* Main Content */}
      <div className="main-content">
        {message && (
          <div className={message.type === 'error' ? 'error-message' : 'success-message'}>
            {message.text}
          </div>
        )}

        <div className="content-header">
          <h1>My Assignments</h1>
          <p>View and manage your event assignments</p>
        </div>

        {/* Statistics Cards */}
        <div className="cards-container">
          <div className="stat-card">
            <h3>Total Assignments</h3>
            <div className="number">{assignments.length}</div>
          </div>
          <div className="stat-card">
            <h3>Pending</h3>
            <div className="number">{pendingAssignments.length}</div>
          </div>
          <div className="stat-card">
            <h3>In Progress</h3>
            <div className="number">{inProgressAssignments.length}</div>
          </div>
          <div className="stat-card">
            <h3>Completed</h3>
            <div className="number">{completedAssignments.length}</div>
          </div>
        </div>

        {/* Volunteer Profile */}
        <div className="form-container">
          <h3>My Profile</h3>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px' }}>
            <div>
              <p><strong>Name:</strong> {volunteer.name}</p>
              <p><strong>Email:</strong> {volunteer.email}</p>
              <p><strong>Phone:</strong> {volunteer.phone}</p>
            </div>
            <div>
              <p><strong>Skills:</strong></p>
              <div style={{ marginTop: '5px' }}>
                {volunteer.skills.length > 0 ? (
                  volunteer.skills.map((skill, index) => (
                    <span 
                      key={index}
                      style={{
                        display: 'inline-block',
                        background: '#3498db',
                        color: 'white',
                        padding: '5px 10px',
                        borderRadius: '15px',
                        fontSize: '12px',
                        marginRight: '5px',
                        marginBottom: '5px'
                      }}
                    >
                      {skill}
                    </span>
                  ))
                ) : (
                  <span style={{ color: '#999' }}>No skills listed</span>
                )}
              </div>
              <p style={{ marginTop: '10px' }}>
                <strong>Status:</strong>{' '}
                <span className={`status-badge status-${volunteer.status}`}>
                  {volunteer.status}
                </span>
              </p>
            </div>
          </div>
        </div>

        {/* Assignments */}
        <div className="table-container">
          <h3>My Event Assignments</h3>
          {assignments.length > 0 ? (
            <table>
              <thead>
                <tr>
                  <th>Event</th>
                  <th>Duty</th>
                  <th>Schedule</th>
                  <th>Status</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {assignments.map(assignment => (
                  <tr key={assignment.id}>
                    <td>
                      <strong>{assignment.eventName}</strong>
                      {assignment.notes && (
                        <div style={{ fontSize: '12px', color: '#666', marginTop: '5px' }}>
                          Notes: {assignment.notes}
                        </div>
                      )}
                    </td>
                    <td>{assignment.duty}</td>
                    <td>{assignment.schedule}</td>
                    <td>
                      <span className={`status-badge status-${assignment.status}`}>
                        {assignment.status}
                      </span>
                    </td>
                    <td>
                      <div className="action-buttons">
                        {assignment.status === 'pending' && (
                          <button
                            className="btn btn-primary"
                            onClick={() => handleUpdateStatus(assignment.id, 'in-progress')}
                          >
                            Start Task
                          </button>
                        )}
                        {assignment.status === 'in-progress' && (
                          <button
                            className="btn btn-success"
                            onClick={() => handleUpdateStatus(assignment.id, 'completed')}
                          >
                            Mark Complete
                          </button>
                        )}
                        {assignment.status === 'completed' && (
                          <span style={{ color: '#2ecc71', fontWeight: 'bold' }}>
                            ✓ Completed
                          </span>
                        )}
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          ) : (
            <div className="empty-state">
              <h3>No assignments yet</h3>
              <p>You don't have any event assignments at the moment.</p>
            </div>
          )}
        </div>

        {/* Pending Tasks Section */}
        {pendingAssignments.length > 0 && (
          <div className="form-container" style={{ background: '#fff3cd', borderLeft: '4px solid #f39c12' }}>
            <h3 style={{ color: '#f39c12' }}>⚠️ Pending Tasks ({pendingAssignments.length})</h3>
            <p>You have {pendingAssignments.length} pending task(s) that need attention.</p>
            <ul style={{ marginTop: '10px', paddingLeft: '20px' }}>
              {pendingAssignments.map(assignment => (
                <li key={assignment.id} style={{ marginBottom: '5px' }}>
                  <strong>{assignment.eventName}</strong> - {assignment.duty}
                </li>
              ))}
            </ul>
          </div>
        )}

        {/* Completed Tasks Section */}
        {completedAssignments.length > 0 && (
          <div className="form-container" style={{ background: '#d4edda', borderLeft: '4px solid #2ecc71' }}>
            <h3 style={{ color: '#2ecc71' }}>✅ Completed Tasks ({completedAssignments.length})</h3>
            <p>Great job! You've completed {completedAssignments.length} task(s).</p>
          </div>
        )}
      </div>
    </div>
  );
}

export default VolunteerDashboard;
